// Import via require so vitest doesn't try to resolve the `.js` extension
// from the source — the file lives in `dist/`. This matches the pattern
// other pre-existing tests in this repo use to load compiled modules.
import { createRequire } from "node:module";
import type { MessageResponseIPC } from "@kena/shared";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const require = createRequire(import.meta.url);
const { RequestTracker } =
	require("../../../../dist/cluster/master/ipc/RequestTracker.js") as typeof import("../../../../dist/cluster/master/ipc/RequestTracker.js");

/**
 * Audit 1.6 — DEFER_TIMEOUT del master vs éxito real del worker
 *
 * The OLD code in InteractionGrpcService.forwardDeferWithBudget set up a
 * tracker with a tight budget. If the worker's POST to Discord finished
 * JUST after the tracker's timer fired:
 *   1. The tracker rejects with "Request X timed out after Yms".
 *   2. The worker's success response lands in
 *      `RequestTracker.resolveRequest`, which finds no pending entry and
 *      logs "Received response for unknown request" — response is lost.
 *   3. The SDK receives `DEFER_TIMEOUT` and sets `deferFailed = true`, so
 *      every subsequent editReply/followUp is auto-suppressed.
 *   4. Meanwhile Discord DID receive the ACK and the followup webhook
 *      works fine.
 *
 * The fix: a late-arriving SUCCESS response should override a
 * tracker-timeout-induced DEFER_TIMEOUT. The cost of getting this wrong
 * (a deferred-but-not-replied interaction that lingers) is much smaller
 * than the cost of the bug (a fully-working interaction the user can't
 * see updates for).
 *
 * Tests below pin the contract:
 *   - `RequestTracker.resolveRequest` for a settled request that returned
 *     success should be observable (via a "late success" hook) so the
 *     caller can convert the timeout into a success.
 *   - The hook must NOT fire for failure responses — a real timeout
 *     masking a worker-reported failure would let a broken defer slip
 *     through.
 */

describe("audit 1.6 — late success response overrides DEFER_TIMEOUT", () => {
	let tracker: RequestTracker;
	let onSettleSpy: ReturnType<typeof vi.fn>;

	beforeEach(() => {
		vi.useFakeTimers();
		tracker = new RequestTracker(30000);
		onSettleSpy = vi.fn();
		tracker.setOnSettle(onSettleSpy);
	});

	afterEach(() => {
		vi.useRealTimers();
	});

	it("a success response arriving AFTER the tracker timed out is preserved as a 'late success'", async () => {
		// 1. Track a request with a tiny budget.
		const promise = tracker.trackRequest("trace-1", 100);
		// 2. Fire the timeout.
		vi.advanceTimersByTime(150);
		// The promise should now have rejected.
		await expect(promise).rejects.toThrow(/timed out/);
		expect(onSettleSpy).toHaveBeenCalledWith("trace-1");

		// 3. Simulate the worker response arriving late with success=true.
		// The audit says: this response used to be dropped with "Received
		// response for unknown request". The fix must let the caller
		// observe it (so the SDK doesn't set deferFailed=true on a defer
		// that actually succeeded).
		const lateResponse: MessageResponseIPC = {
			success: true,
			data: { ok: true },
			timestamp: new Date().toISOString(),
			request_id: "trace-1",
			status: "OK" as any
		} as any;

		const resolved = tracker.resolveRequest("trace-1", lateResponse);
		// `resolved` is still `false` (the pending promise already
		// rejected on timeout — there's nothing to resolve). The fix
		// exposes the late success via a separate API: `consumeLateSuccess`.
		expect(resolved).toBe(false);

		// The real contract: the caller can retrieve the late success
		// response and convert its own DEFER_TIMEOUT to OK.
		const consumed = tracker.consumeLateSuccess("trace-1");
		expect(consumed).toEqual(lateResponse);

		// consumeLateSuccess is one-shot — a second call returns null.
		expect(tracker.consumeLateSuccess("trace-1")).toBeNull();
	});

	it("a failure response arriving AFTER the tracker timed out is NOT preserved", async () => {
		// The fix must NOT help failure responses slip through. A real
		// defer failure should stay a failure regardless of timing.
		const promise = tracker.trackRequest("trace-2", 100);
		vi.advanceTimersByTime(150);
		await expect(promise).rejects.toThrow(/timed out/);

		const failureResponse: MessageResponseIPC = {
			success: false,
			data: null,
			timestamp: new Date().toISOString(),
			request_id: "trace-2",
			code: 10062,
			message: "Unknown interaction"
		} as any;

		const resolved = tracker.resolveRequest("trace-2", failureResponse);
		// A late failure must NOT be observable as "resolved" — the
		// audit only fixes the late-SUCCESS case.
		expect(resolved).toBe(false);
	});

	it("a normal (in-flight) resolve still works unchanged", async () => {
		const promise = tracker.trackRequest("trace-3", 1000);
		const ok = tracker.resolveRequest("trace-3", {
			success: true,
			data: { ok: true },
			timestamp: new Date().toISOString(),
			request_id: "trace-3"
		} as any);
		expect(ok).toBe(true);
		const result = await promise;
		expect(result.success).toBe(true);
	});

	it("the late success response is delivered to a listener registered after the timeout", async () => {
		// More realistic contract: a separate hook fires when a
		// success response arrives for a request that already timed
		// out. The InteractionGrpcService subscribes to this hook
		// once per request and uses it to convert DEFER_TIMEOUT to OK.
		const lateSuccessHook = vi.fn();
		tracker.setOnLateSuccess((request_id, response) => {
			lateSuccessHook(request_id, response);
		});

		const promise = tracker.trackRequest("trace-4", 100);
		vi.advanceTimersByTime(150);
		await expect(promise).rejects.toThrow(/timed out/);

		const lateResponse: MessageResponseIPC = {
			success: true,
			data: { ok: true },
			timestamp: new Date().toISOString(),
			request_id: "trace-4",
			status: "OK" as any
		} as any;

		tracker.resolveRequest("trace-4", lateResponse);
		expect(lateSuccessHook).toHaveBeenCalledWith("trace-4", lateResponse);
	});
});

