9	export interface GrpcRateLimiterOptions {
10		moduleRule: RateLimitRule;
11		rpcRules?: Record<string, Partial<RateLimitRule>>;
12		/**
13		 * Techo de peticiones EN VUELO por módulo. `0` o ausente = sin techo.
14		 *
15		 * Es el freno que faltaba, y es distinto del de TASA: la tasa cuenta cuántas
16		 * ENTRAN por ventana, y en el incidente del 11-08-2026 los ~115 req/s reales
17		 * quedaron muy por debajo del techo de 300/s, así que no se activó nunca. Lo que
18		 * tumbó al core no fue el ritmo de entrada: fue la ACUMULACIÓN — con 5 s de
19		 * deadline y un core que ya no contestaba, llegó a tener del orden de 575
20		 * peticiones vivas a la vez, cada una reteniendo su payload y su closure.
21		 *
22		 * En tráfico sano las peticiones en vuelo de un módulo son unidades: entran a
23		 * ~100/s y se resuelven en decenas de milisegundos. Un techo alto no molesta a
24		 * nadie y corta en seco al módulo desbocado, que es justo lo que se quiere —
25		 * porque el core lo comparten los diez módulos y ahogarlo se los lleva a todos.
26		 */
27		maxInFlightPerModule?: number;
28		logger?: typeof logger;
29		logType?: string;
30	}
31	
32	export interface RateLimitDecision {
33		allowed: boolean;
34		retryAfterMs: number;
35		reason: "module" | "rpc" | "in_flight" | "none";
36	}
37	
38	type BucketState = {
39		windowStart: number;
40		count: number;
41	};
42	
43	type UnaryHandler<Req, Res> = (call: grpc.ServerUnaryCall<Req, Res>, callback: grpc.sendUnaryData<Res>) => void;
44	
45	function sanitizeRule(rule: Partial<RateLimitRule> | undefined, fallback: RateLimitRule): RateLimitRule {
46		const maxRequests = Number(rule?.maxRequests ?? fallback.maxRequests);
47		const windowMs = Number(rule?.windowMs ?? fallback.windowMs);
48	
49		return {
50			maxRequests: Number.isFinite(maxRequests) ? Math.max(1, Math.floor(maxRequests)) : fallback.maxRequests,
51			windowMs: Number.isFinite(windowMs) ? Math.max(1_000, Math.floor(windowMs)) : fallback.windowMs
52		};
53	}
54	
55	export class GrpcRateLimiter {
56		private readonly moduleRule: RateLimitRule;
57		private readonly rpcRules: Map<string, RateLimitRule>;
58		private readonly buckets = new Map<string, BucketState>();
59		private readonly logger: typeof logger;
60		private readonly logType: string;
61		private readonly metrics = {
62			allowed: 0,
63			blocked: 0,
64			byRpc: new Map<string, { allowed: number; blocked: number }>()
65		};
66		/** Peticiones vivas por módulo. Sube al admitir y baja al responder. */
67		private readonly inFlight = new Map<string, number>();
68		private readonly maxInFlightPerModule: number;
69		/** Rechazos por techo de concurrencia en el periodo, para la línea de carga. */
70		private inFlightRejections = 0;
71		/** Máximo simultáneo visto en el periodo: es el número con el que calibrar. */
72		private inFlightPeak = 0;
73	
74		constructor(options: GrpcRateLimiterOptions) {
75			this.moduleRule = sanitizeRule(options.moduleRule, { maxRequests: 120, windowMs: 60_000 });
76			this.rpcRules = new Map(
77				Object.entries(options.rpcRules || {}).map(([rpc, rule]) => [rpc, sanitizeRule(rule, this.moduleRule)])
78			);
79			this.logger = options.logger ?? logger;
80			this.logType = options.logType ?? LogType.GRPC;
81			const ceiling = Number(options.maxInFlightPerModule ?? 0);
82			this.maxInFlightPerModule = Number.isFinite(ceiling) && ceiling > 0 ? Math.floor(ceiling) : 0;
83		}
84	
85		/**
86		 * Reserva un hueco de concurrencia, o `false` si el módulo ya está en su techo.
87		 *
88		 * Va SEPARADO de `checkAndConsume` porque su contrapartida (`releaseInFlight`)
89		 * tiene que correr cuando la petición se resuelve, y eso sólo lo sabe quien
90		 * envuelve el handler. Un llamante que use `checkAndConsume` a pelo no participa
91		 * del techo — es explícito, no un olvido.
92		 */
93		public tryAcquireInFlight(moduleKey: string): boolean {
94			const live = this.inFlight.get(moduleKey) ?? 0;
95			if (this.maxInFlightPerModule > 0 && live >= this.maxInFlightPerModule) {
96				this.inFlightRejections++;
97				return false;
98			}
99			const next = live + 1;
100			this.inFlight.set(moduleKey, next);
101			if (next > this.inFlightPeak) this.inFlightPeak = next;
102			return true;
103		}
104	
105		public releaseInFlight(moduleKey: string): void {
106			const live = (this.inFlight.get(moduleKey) ?? 0) - 1;
107			// Se borra la entrada al llegar a cero: si no, el mapa acumularía una clave
108			// por cada módulo que haya hablado alguna vez desde el arranque.
109			if (live <= 0) this.inFlight.delete(moduleKey);
110			else this.inFlight.set(moduleKey, live);
111		}
112	
113		/** Peticiones vivas de un módulo (o de todos si no se da). Para tests y métricas. */
114		public getInFlight(moduleKey?: string): number {
115			if (moduleKey !== undefined) return this.inFlight.get(moduleKey) ?? 0;
116			let total = 0;
117			for (const live of this.inFlight.values()) total += live;
118			return total;
119		}
120	
121		public checkAndConsume(moduleKey: string | undefined, rpcName: string): RateLimitDecision {
122			const normalizedModuleKey = moduleKey?.trim() || "anonymous";
123			const moduleDecision = this.consumeBucket(`mod:${normalizedModuleKey}`, this.moduleRule);
124			if (!moduleDecision.allowed) {
125				this.recordDecision(normalizedModuleKey, rpcName, false);
126				return {
127					allowed: false,
128					retryAfterMs: moduleDecision.retryAfterMs,
129					reason: "module"
130				};
131			}
132	
133			const rpcRule = this.rpcRules.get(rpcName);
134			if (rpcRule) {
135				const rpcDecision = this.consumeBucket(`rpc:${normalizedModuleKey}:${rpcName}`, rpcRule);
136				if (!rpcDecision.allowed) {
137					this.recordDecision(normalizedModuleKey, rpcName, false);
138					return {
139						allowed: false,
140						retryAfterMs: rpcDecision.retryAfterMs,
141						reason: "rpc"
142					};
143				}
144			}
145	
146			this.recordDecision(normalizedModuleKey, rpcName, true);
147			return {
148				allowed: true,
149				retryAfterMs: 0,
150				reason: "none"
151			};
152		}
153	
154		public wrapUnary<Req, Res>(
155			rpcName: string,
156			getModuleKey: (call: grpc.ServerUnaryCall<Req, Res>) => string | undefined,
157			handler: UnaryHandler<Req, Res>
158		): UnaryHandler<Req, Res> {
159			return (call, callback) => {
160				const moduleKey = getModuleKey(call);
161				const decision = this.checkAndConsume(moduleKey, rpcName);
162				if (!decision.allowed) {
163					const retryAfterSeconds = Math.ceil(decision.retryAfterMs / 1000);
164					this.logger.warn?.(
165						LogType.GRPC,
166						`Rate limit exceeded for module=${moduleKey || "anonymous"} rpc=${rpcName} scope=${decision.reason}`
167					);
168					callback({
169						code: grpc.status.RESOURCE_EXHAUSTED,
170						message: `Rate limit exceeded for ${rpcName}. Retry in ${retryAfterSeconds}s`
171					} as grpc.ServiceError);
172					return;
173				}
174	
175				// Techo de CONCURRENCIA, después del de tasa. Rechazar aquí es mucho mejor
176				// para el llamante que dejarle agotar su deadline: recibe un error al
177				// instante en vez de esperar 5 s a nada.
178				const normalizedModuleKey = moduleKey?.trim() || "anonymous";
179				if (!this.tryAcquireInFlight(normalizedModuleKey)) {
180					this.logger.warn?.(
181						LogType.GRPC,
182						`In-flight ceiling reached for module=${normalizedModuleKey} rpc=${rpcName} (${this.maxInFlightPerModule}); request rejected`
183					);
184					callback({
185						code: grpc.status.RESOURCE_EXHAUSTED,
186						message: `Too many in-flight requests for module ${normalizedModuleKey}. Slow down.`
187					} as grpc.ServiceError);
188					return;
189				}
190	
191				// El hueco se libera cuando la petición se resuelve, sea como sea. El guard
192				// de `settled` no es paranoia: un handler que llame al callback dos veces
193				// —por un `catch` que responde después de un camino que ya respondió—
194				// desbalancearía el contador, y un contador que sólo sube acaba cerrando el
195				// módulo entero a base de falsos «demasiadas en vuelo».
196				let settled = false;
197				// Los argumentos se reenvían TAL CUAL, no uno a uno: pasarlos con nombre
198				// (`err, value, trailer, flags`) convertía una llamada de dos argumentos en
199				// una de cuatro con dos `undefined` inventados, y eso ya cambia lo que ve
200				// grpc-js — además de romper cualquier aserto sobre la forma de la respuesta.
201				const release = ((...args: Parameters<grpc.sendUnaryData<Res>>): void => {
202					if (!settled) {
203						settled = true;
204						this.releaseInFlight(normalizedModuleKey);
205					}
206					callback(...args);
207				}) as grpc.sendUnaryData<Res>;
208	
209				// Un handler que lance de forma SÍNCRONA no llegaría a su callback nunca, y
210				// el hueco se quedaría cogido para siempre.
211				try {
212					handler(call, release);
213				} catch (err) {
214					if (!settled) {
215						settled = true;
216						this.releaseInFlight(normalizedModuleKey);
217					}
218					throw err;
219				}
220			};
221		}
222	
223		private consumeBucket(bucketKey: string, rule: RateLimitRule): { allowed: boolean; retryAfterMs: number } {
224			const now = Date.now();
225			const current = this.buckets.get(bucketKey);
226	
227			if (!current || now - current.windowStart >= rule.windowMs) {
228				this.buckets.set(bucketKey, { windowStart: now, count: 1 });
229				return { allowed: true, retryAfterMs: 0 };
230			}
231	
232			if (current.count >= rule.maxRequests) {
233				return {
234					allowed: false,
235					retryAfterMs: Math.max(0, current.windowStart + rule.windowMs - now)
236				};
237			}
238	
239			current.count++;
240			return { allowed: true, retryAfterMs: 0 };
241		}
242	
243		private recordDecision(_moduleKey: string, rpcName: string, allowed: boolean): void {
244			if (allowed) this.metrics.allowed++;
245			else this.metrics.blocked++;
246	
247			const byRpc = this.metrics.byRpc.get(rpcName) || { allowed: 0, blocked: 0 };
248			if (allowed) byRpc.allowed++;
249			else byRpc.blocked++;
250			this.metrics.byRpc.set(rpcName, byRpc);
251		}
252	
253		/**
254		 * Instantánea del periodo y **puesta a cero**.
255		 *
256		 * Estas cuentas se llevaban desde el primer día y no las leía nadie: eran
257		 * contabilidad muerta que se tiraba al morir el proceso. Se drenan en vez de
258		 * acumularse desde el arranque porque lo que interesa es la TASA —«este minuto
259		 * han entrado 6.900 y he bloqueado 12»—, no un total desde el último
260		 * despliegue, que no dice nada de si algo va mal ahora.
261		 *
262		 * `topRpcs` sale ordenado por volumen y recortado: el objetivo es una línea de
263		 * log legible, no un volcado de los cien RPCs del catálogo.
264		 */
265		public drainMetrics(topN = 3): {
266			allowed: number;
267			blocked: number;
268			topRpcs: Array<{ rpc: string; allowed: number; blocked: number }>;
269			/** Máximo de peticiones simultáneas de un módulo en el periodo. */
270			inFlightPeak: number;
271			/** Rechazos por techo de concurrencia en el periodo. */
272			inFlightRejected: number;
273		} {
274			const topRpcs = [...this.metrics.byRpc.entries()]
275				.map(([rpc, counts]) => ({ rpc, ...counts }))
276				.sort((a, b) => b.allowed + b.blocked - (a.allowed + a.blocked))
277				.slice(0, topN);
278			const snapshot = {
279				allowed: this.metrics.allowed,
280				blocked: this.metrics.blocked,
281				topRpcs,
282				inFlightPeak: this.inFlightPeak,
283				inFlightRejected: this.inFlightRejections
284			};
285	
286			this.metrics.allowed = 0;
287			this.metrics.blocked = 0;
288			this.metrics.byRpc.clear();
289			this.inFlightRejections = 0;
290			// El pico se reinicia a lo que hay VIVO ahora, no a cero: si hay 40 peticiones
291			// en vuelo en este instante, el pico del periodo siguiente no puede ser menor.
292			this.inFlightPeak = this.getInFlight();
293	
294			return snapshot;
295		}
296	
297		/**
298		 * Evict buckets whose window has fully elapsed and which would be
299		 * reset on the next call anyway. Without this, every distinct
300		 * (module, rpc) pair seen since boot keeps a dead entry in the map.
301		 * The next `consumeBucket` call resets entries it actually uses, so
302		 * dropping them here only removes truly idle buckets.
303		 */
304		public sweepStaleBuckets(now: number = Date.now()): number {
305			let removed = 0;
306			for (const [key, state] of this.buckets) {
307				const rule = key.startsWith("rpc:") ? this.rpcRules.get(key.split(":").slice(2).join(":")) : undefined;
308				const windowMs = rule?.windowMs ?? this.moduleRule.windowMs;
309				if (now - state.windowStart >= windowMs * 2) {
310					this.buckets.delete(key);
311					removed++;
312				}
313			}
314			return removed;
315		}
316	}
