import { LogType, logger } from "../../../shared/Logger.js";
import type { MessageResponseIPC } from "../../../shared/types/cluster/message.js";

interface PendingRequest {
	resolve: (value: MessageResponseIPC) => void;
	reject: (error: Error) => void;
	timeout: NodeJS.Timeout;
	timestamp: number;
}

/**
 * Todos los trackers vivos del proceso.
 *
 * Existe para poder MEDIR: hay un tracker por servicio gRPC (diez), cada uno con
 * su `pendingRequests` privado, y hasta ahora `getPendingCount()` no lo llamaba
 * NADIE — la profundidad de la cola de peticiones en vuelo, que es la señal que
 * habría delatado la saturación del core antes de que un usuario dijera «no
 * funciona», se calculaba y se tiraba.
 *
 * Un registro aquí evita tener que abrir un getter público en cada uno de los
 * diez servicios, y hace que un servicio nuevo entre en la medición sin que nadie
 * se acuerde de añadirlo.
 */
const liveTrackers = new Set<RequestTracker>();

/** Peticiones en vuelo AHORA MISMO, sumando todos los servicios. */
export function pendingRequestsSnapshot(): { total: number; trackers: number; max: number } {
	let total = 0;
	let max = 0;
	for (const tracker of liveTrackers) {
		const pending = tracker.getPendingCount();
		total += pending;
		if (pending > max) max = pending;
	}
	return { total, trackers: liveTrackers.size, max };
}

export class RequestTracker {
	private readonly pendingRequests = new Map<string, PendingRequest>();
	/**
	 * Audit 1.6: a small ring of late-arriving success responses for
	 * requests that already timed out. We keep them around for a brief
	 * window so the caller (InteractionGrpcService) can convert a
	 * tracker-induced DEFER_TIMEOUT into a real success when the worker's
	 * POST actually completed before Discord rejected anything.
	 */
	private readonly lateSuccesses = new Map<string, MessageResponseIPC>();
	/**
	 * Bounded so the ring can't grow under a sustained stream of late
	 * successes. 256 is a comfortable upper bound for the rate at which
	 * a worker might legitimately be late (we keep the most recent 256).
	 */
	private static readonly LATE_SUCCESS_MAX = 256;
	private readonly defaultTimeout: number;
	private onSettle?: (request_id: string) => void;
	private onLateSuccess?: (request_id: string, response: MessageResponseIPC) => void;

	constructor(defaultTimeout = 30000) {
		// 30 seconds default
		this.defaultTimeout = defaultTimeout;
		// Se apunta al registro para que la profundidad de la cola sea medible sin
		// abrir un getter en cada servicio. Los trackers viven lo que el proceso, así
		// que no hace falta darse de baja.
		liveTrackers.add(this);
	}

	/**
	 * Register a callback fired whenever a request is fully settled (resolve,
	 * reject, timeout, or supersede). Used by ClusterIPC to clear its
	 * `pendingByCluster` rejector so a later cluster-exit doesn't try to
	 * invoke a no-op `rejectRequest` and spam "Cannot reject unknown
	 * request" warnings.
	 */
	setOnSettle(cb: (request_id: string) => void): void {
		this.onSettle = cb;
	}

	/**
	 * Audit 1.6: register a callback fired when a success response arrives
	 * for a request that has already timed out. The InteractionGrpcService
	 * uses this to convert a tracker-induced DEFER_TIMEOUT into OK so the
	 * SDK doesn't set deferFailed=true on a defer that actually succeeded.
	 */
	setOnLateSuccess(cb: (request_id: string, response: MessageResponseIPC) => void): void {
		this.onLateSuccess = cb;
	}

	/**
	 * Track a request and return a promise that resolves when the response arrives
	 */
	trackRequest(request_id: string, timeoutMs?: number): Promise<MessageResponseIPC> {
		// Collision: reject the previous holder immediately and clear its
		// timer before installing the new one. Without this, the prior
		// promise would leak until its 30s timer fires AND its expiry would
		// delete the NEW entry — making the new caller's response land as
		// "Received response for unknown request" and itself time out.
		const prior = this.pendingRequests.get(request_id);
		if (prior) {
			clearTimeout(prior.timeout);
			this.pendingRequests.delete(request_id);
			prior.reject(new Error(`Request ${request_id} superseded by a new tracker entry (trace_id collision)`));
			this.onSettle?.(request_id);
			logger.warn(LogType.CLUSTER, `Request ${request_id} was already tracked — rejected the prior promise`);
		}

		return new Promise<MessageResponseIPC>((resolve, reject) => {
			const timeout = setTimeout(() => {
				this.pendingRequests.delete(request_id);
				this.onSettle?.(request_id);
				reject(new Error(`Request ${request_id} timed out after ${timeoutMs || this.defaultTimeout}ms`));
			}, timeoutMs || this.defaultTimeout);

			this.pendingRequests.set(request_id, {
				resolve,
				reject,
				timeout,
				timestamp: Date.now()
			});

			logger.info(
				LogType.CLUSTER,
				`Tracking request ${request_id} with timeout ${timeoutMs || this.defaultTimeout}ms`
			);
		});
	}

	/**
	 * Resolve a tracked request with a response
	 */
	resolveRequest(request_id: string, response: MessageResponseIPC): boolean {
		const pending = this.pendingRequests.get(request_id);
		if (!pending) {
			// Audit 1.6: a success response arriving AFTER the tracker
			// timed out used to be dropped silently. We now keep a
			// bounded ring of late successes and fire the onLateSuccess
			// hook so the caller can convert the timeout into OK. A
			// failure response is still discarded — letting late
			// failures slip through would let a real defer failure
			// masquerade as a late success.
			if (response?.success) {
				this.recordLateSuccess(request_id, response);
				logger.warn(LogType.CLUSTER, `[late_success] received success for already-settled request ${request_id}`);
				this.onLateSuccess?.(request_id, response);
			} else {
				logger.warn(LogType.CLUSTER, `Received response for unknown request ${request_id}`);
			}
			return false;
		}

		clearTimeout(pending.timeout);
		this.pendingRequests.delete(request_id);
		this.onSettle?.(request_id);

		const duration = Date.now() - pending.timestamp;
		logger.info(LogType.CLUSTER, `Request ${request_id} resolved in ${duration}ms`);

		pending.resolve(response);
		return true;
	}

	/**
	 * Audit 1.6: bounded ring of late-arriving success responses. The
	 * oldest entry is evicted FIFO when the cap is hit so a sustained
	 * stream of late successes can't grow the Map without bound.
	 */
	private recordLateSuccess(request_id: string, response: MessageResponseIPC): void {
		if (this.lateSuccesses.size >= RequestTracker.LATE_SUCCESS_MAX) {
			const oldest = this.lateSuccesses.keys().next().value;
			if (oldest !== undefined) this.lateSuccesses.delete(oldest);
		}
		this.lateSuccesses.set(request_id, response);
	}

	/**
	 * Audit 1.6: lookup (and clear) a late success. The InteractionGrpcService
	 * calls this from its catch block after a tracker-timeout to check
	 * whether the worker actually completed the defer despite the timer.
	 */
	consumeLateSuccess(request_id: string): MessageResponseIPC | null {
		const response = this.lateSuccesses.get(request_id);
		if (response) this.lateSuccesses.delete(request_id);
		return response ?? null;
	}

	/**
	 * Reject a tracked request with an error
	 */
	rejectRequest(request_id: string, error: Error): boolean {
		const pending = this.pendingRequests.get(request_id);
		if (!pending) {
			logger.warn(LogType.CLUSTER, `Cannot reject unknown request ${request_id}`);
			return false;
		}

		clearTimeout(pending.timeout);
		this.pendingRequests.delete(request_id);
		this.onSettle?.(request_id);

		logger.error(LogType.CLUSTER, `Request ${request_id} rejected:`, error);

		pending.reject(error);
		return true;
	}

	/**
	 * Get the number of pending requests
	 */
	getPendingCount(): number {
		return this.pendingRequests.size;
	}

	/**
	 * Clear all pending requests (useful for testing or shutdown)
	 */
	clearAll(): void {
		for (const pending of this.pendingRequests.values()) {
			clearTimeout(pending.timeout);
			pending.reject(new Error("Request tracker cleared"));
		}
		this.pendingRequests.clear();
		this.lateSuccesses.clear();
		logger.info(LogType.CLUSTER, "All pending requests cleared");
	}
}

