private static readonly LATE_SUCCESS_MAX = 256;
private readonly defaultTimeout: number;
/**
 * Techo de peticiones EN VUELO simultáneas. Auditoría 2026-08-11: a
 * diferencia de MessageIngestBuffer (que sí tiene `maxBufferedMessages`),
 * `pendingRequests` no tenía techo — cada entrada retiene sus closures
 * resolve/reject, un `Timeout` y el payload completo (hasta 16 MiB por
 * `max_receive_message_length`, server.ts) mientras se espera al worker,
 * así que si las peticiones entran más rápido de lo que se resuelven el
 * Map crece hasta agotar el heap. Es la explicación que mejor encaja con
 * los 10 GB de RAM del incidente.
 *
 * 256 por servicio, igual que `MAX_IN_FLIGHT_PER_MODULE` en server.ts: en
 * tráfico sano las peticiones vivas de un servicio son unidades, así que
 * 256 es un margen amplio que no molesta a nadie sano y corta bien por
 * debajo del orden de magnitud (~575) que produjo el incidente.
 */
private static readonly DEFAULT_MAX_PENDING = 256;
private readonly maxPending: number;
/** Peticiones rechazadas de entrada por haber llegado con el techo lleno. */
private droppedRequests = 0;
private onSettle?: (request_id: string) => void;
private onLateSuccess?: (request_id: string, response: MessageResponseIPC) => void;

constructor(defaultTimeout = 30000, maxPending = RequestTracker.DEFAULT_MAX_PENDING) {
	// 30 seconds default
	this.defaultTimeout = defaultTimeout;
	this.maxPending = maxPending;
	// Se apunta al registro para que la profundidad de la cola sea medible sin
	// abrir un getter en cada servicio. Los trackers viven lo que el proceso, así
	// que no hace falta darse de baja.
	liveTrackers.add(this);
}

