// Import via require so vitest doesn't try to resolve the `.js` extension
// from the source — the file lives in `dist/`. This matches the pattern
// other pre-existing tests in this repo use to load compiled modules.
import { createRequire } from "node:module";
import type { MessageResponseIPC } from "@kena/shared";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const require = createRequire(import.meta.url);
const { RequestTracker, pendingRequestsSnapshot } =
	require("../../../../dist/cluster/master/ipc/RequestTracker.js") as typeof import("../../../../dist/cluster/master/ipc/RequestTracker.js");

/**
 * Auditoría 2026-08-11 — `pendingRequests` sin `maxPending`
 *
 * A diferencia de MessageIngestBuffer (que sí tiene un tope duro de filas en
 * memoria), RequestTracker.pendingRequests no tenía techo: cada entrada
 * retiene sus closures, un Timeout y el payload completo mientras se espera
 * al worker, así que si las peticiones entran más rápido de lo que se
 * resuelven el Map crece sin freno. Estos tests pinan el contrato del fix:
 * un tracker con el techo lleno rechaza peticiones NUEVAS de inmediato en
 * vez de encolarlas.
 */
describe("RequestTracker — techo de pendingRequests (maxPending)", () => {
	beforeEach(() => {
		vi.useFakeTimers();
	});

	afterEach(() => {
		vi.useRealTimers();
	});

	function response(request_id: string): MessageResponseIPC {
		return {
			success: true,
			data: { ok: true },
			timestamp: new Date().toISOString(),
			request_id
		} as any;
	}

	it("rejects a new request immediately once the tracker is at its maxPending cap", async () => {
		const tracker = new RequestTracker(30000, 2);

		const p1 = tracker.trackRequest("req-1", 5000);
		const p2 = tracker.trackRequest("req-2", 5000);
		expect(tracker.getPendingCount()).toBe(2);

		// Third request arrives while the first two are still in flight — the
		// cap is full, so it must be rejected immediately, without ever being
		// added to pendingRequests or waiting for a timeout.
		await expect(tracker.trackRequest("req-3", 5000)).rejects.toThrow(/rejected/);
		expect(tracker.getPendingCount()).toBe(2);

		// The two originally tracked requests are unaffected by the rejection.
		tracker.resolveRequest("req-1", response("req-1"));
		tracker.resolveRequest("req-2", response("req-2"));
		await expect(p1).resolves.toMatchObject({ request_id: "req-1" });
		await expect(p2).resolves.toMatchObject({ request_id: "req-2" });
	});

	it("accepts a new request again once a slot frees up", async () => {
		const tracker = new RequestTracker(30000, 1);

		const p1 = tracker.trackRequest("req-1", 5000);
		await expect(tracker.trackRequest("req-2", 5000)).rejects.toThrow(/rejected/);

		tracker.resolveRequest("req-1", response("req-1"));
		await p1;

		// The slot freed by resolveRequest is now available again.
		const p3 = tracker.trackRequest("req-3", 5000);
		expect(tracker.getPendingCount()).toBe(1);
		tracker.resolveRequest("req-3", response("req-3"));
		await expect(p3).resolves.toMatchObject({ request_id: "req-3" });
	});

	it("a same-id collision still supersedes the prior entry even when the tracker is full", async () => {
		const tracker = new RequestTracker(30000, 1);

		const p1 = tracker.trackRequest("req-1", 5000);
		// Same request_id: this is a collision, not a new entry, so it must
		// not be rejected by the cap even though the tracker is already full.
		const p1Again = tracker.trackRequest("req-1", 5000);

		await expect(p1).rejects.toThrow(/superseded/);
		expect(tracker.getPendingCount()).toBe(1);

		tracker.resolveRequest("req-1", response("req-1"));
		await expect(p1Again).resolves.toMatchObject({ request_id: "req-1" });
	});

	it("counts cap rejections and surfaces them via pendingRequestsSnapshot, draining per call", async () => {
		const tracker = new RequestTracker(30000, 1);
		tracker.trackRequest("req-1", 5000);

		await expect(tracker.trackRequest("req-2", 5000)).rejects.toThrow(/rejected/);
		await expect(tracker.trackRequest("req-3", 5000)).rejects.toThrow(/rejected/);

		const first = pendingRequestsSnapshot();
		expect(first.dropped).toBeGreaterThanOrEqual(2);

		// drainDroppedCount resets on read, so a snapshot right after must not
		// double-count the same rejections.
		const second = pendingRequestsSnapshot();
		expect(second.dropped).toBe(0);

		tracker.clearAll();
	});
});

